INSERT INTO public.sfo_team (team_id, tenant_id, team_code, team_name, description, default_sla_days, is_active, display_order, created_at) VALUES
	(1, 1, 'AUTHORISATIONS', 'Authorisations / Switch Ops', 'Owns authorisation message quality and the switch. Fixes the cause of integrity and processing-excellence penalties.', 7, true, 1, '2026-11-18 10:16:00.91757'),
	(2, 1, 'CLEARING_DISPUTES', 'Clearing & Disputes', 'Owns clearing cut-offs and dispute SLAs. Fixes late presentment and chargeback non-compliance.', 7, true, 2, '2026-11-18 10:16:00.91757'),
	(3, 1, 'SCHEME_RELATIONS', 'Scheme Relations', 'Owns the billing relationship: raises disputes with the scheme, keeps ICA/BID registration and contracted rates correct.', 14, true, 3, '2026-11-18 10:16:00.91757'),
	(4, 1, 'PRODUCT_PRICING', 'Product & Pricing', 'Owns routing, DCC and merchant mix — the commercial decisions behind cross-border cost.', 21, true, 4, '2026-11-18 10:16:00.91757'),
	(5, 1, 'FINANCE', 'Finance', 'Monitors the cost of doing business. Receives what is correct but worth watching, not what is disputable.', 30, true, 5, '2026-11-18 10:16:00.91757');


