--
-- Data for Name: tenant_provision_script; Type: TABLE DATA; Schema: public; Owner: -
--

INSERT INTO public.tenant_provision_script (script_id, script_name, script_order, description, script_sql, is_active, continue_on_error, created_by, created_at, updated_at) VALUES
	(1, 'Default tenant settings', 10, 'Seeds the SSO, password-policy and session settings a new bank needs. Mirrors the schema.sql startup seeds but runs immediately at tenant creation.', 'INSERT INTO tenant_setting (tenant_id, setting_key, setting_value, setting_type) VALUES
(${TENANT_ID}, ''sso_enabled'', ''false'', ''BOOLEAN''),
(${TENANT_ID}, ''sso_provider'', ''MICROSOFT'', ''STRING''),
(${TENANT_ID}, ''sso_client_id'', '''', ''STRING''),
(${TENANT_ID}, ''sso_tenant_id'', '''', ''STRING''),
(${TENANT_ID}, ''sso_client_secret'', '''', ''STRING''),
(${TENANT_ID}, ''password_history_count'', ''5'', ''NUMBER''),
(${TENANT_ID}, ''password_min_length'', ''8'', ''NUMBER''),
(${TENANT_ID}, ''max_failed_logins'', ''5'', ''NUMBER''),
(${TENANT_ID}, ''lockout_duration_minutes'', ''15'', ''NUMBER''),
(${TENANT_ID}, ''password_reset_token_expiry_hours'', ''1'', ''NUMBER''),
(${TENANT_ID}, ''security.session_timeout_minutes'', ''30'', ''NUMBER'')
ON CONFLICT (tenant_id, setting_key) DO NOTHING', true, false, 'schema.sql', '2026-11-18 10:15:17.748251', NULL),
	(2, 'Default email templates', 20, 'Copies the seed tenant''s active email templates (statements, reports, campaigns) to the new bank so Email Manager works out of the box.', 'INSERT INTO email_template_config (tenant_id, name, template_type, subject_template, body_html, body_text, is_active, is_default_for_type, created_by)
SELECT ${TENANT_ID}, s.name, s.template_type, s.subject_template, s.body_html, s.body_text, TRUE, s.is_default_for_type, ''provisioning''
FROM email_template_config s
WHERE s.tenant_id = 1 AND s.is_active = TRUE AND ${TENANT_ID} <> 1
AND NOT EXISTS (
    SELECT 1 FROM email_template_config e
    WHERE e.tenant_id = ${TENANT_ID} AND e.template_type = s.template_type AND e.name = s.name
)', true, true, 'schema.sql', '2026-11-18 10:15:17.753043', NULL),
	(3, 'default-team-lead', 10, 'Create the default team lead for auto-assigning unmapped sales users', 'INSERT INTO sales_team_mapping (tenant_id, team_lead_name, team_lead_email, is_default) VALUES (${TENANT_ID}, ''Default Team Lead'', ''default-lead@acquira.com'', true) ON CONFLICT (tenant_id, team_lead_email) DO UPDATE SET is_default = true', true, false, 'system', '2026-11-18 10:15:22.847854', NULL),
	(4, 'default-country-lead', 20, 'Create the default country lead (team leads with no country lead roll up here)', 'INSERT INTO sales_country_lead (tenant_id, country_lead_name, country_lead_email, is_default) VALUES (${TENANT_ID}, ''Default Country Lead'', ''default-country-lead@acquira.com'', true) ON CONFLICT (tenant_id, country_lead_email) DO NOTHING', true, true, 'system', '2026-11-18 10:15:22.851214', NULL),
	(5, 'tenant-settings-defaults', 30, 'Per-tenant default settings: SSO toggle/keys, password policy, lockout', 'INSERT INTO tenant_setting (tenant_id, setting_key, setting_value, setting_type) VALUES (${TENANT_ID}, ''sso_enabled'', ''false'', ''BOOLEAN''), (${TENANT_ID}, ''sso_provider'', ''MICROSOFT'', ''STRING''), (${TENANT_ID}, ''sso_client_id'', '''', ''STRING''), (${TENANT_ID}, ''sso_tenant_id'', '''', ''STRING''), (${TENANT_ID}, ''sso_client_secret'', '''', ''STRING''), (${TENANT_ID}, ''password_history_count'', ''5'', ''NUMBER''), (${TENANT_ID}, ''password_min_length'', ''8'', ''NUMBER''), (${TENANT_ID}, ''max_failed_logins'', ''5'', ''NUMBER''), (${TENANT_ID}, ''lockout_duration_minutes'', ''15'', ''NUMBER''), (${TENANT_ID}, ''password_reset_token_expiry_hours'', ''1'', ''NUMBER'') ON CONFLICT (tenant_id, setting_key) DO NOTHING', true, false, 'system', '2026-11-18 10:15:22.85417', NULL),
	(6, 'default-email-templates', 40, 'Copy the default email templates (Statement/Welcome/Alert) from the earliest tenant', 'INSERT INTO email_template_config (tenant_id, name, template_type, subject_template, body_html, is_active, is_default_for_type) SELECT ${TENANT_ID}, name, template_type, subject_template, body_html, is_active, is_default_for_type FROM email_template_config WHERE tenant_id = (SELECT MIN(tenant_id) FROM tenant) AND ${TENANT_ID} <> (SELECT MIN(tenant_id) FROM tenant) ON CONFLICT DO NOTHING', true, true, 'system', '2026-11-18 10:15:22.856782', NULL),
	(7, 'tenant-partitions', 5, 'Create the tenant''s physical partition set (fact_transaction + 9 summary tables, current + next year). Requires REBUILD_TENANT_LIST_PARTITIONING.sql to have been applied; fails harmlessly before that.', 'SELECT ensure_tenant_partitions(${TENANT_ID})', true, true, 'system', '2026-11-18 10:15:23.631219', NULL);


